insert into public.destinations (id, name, country, docs, events, health, people, packing, fof_visited_count, spring_trip_count) values
  ('dest_japan', 'Japan', 'Japan', 'No visa needed for tourist stays up to 90 days. Passport must be valid for your whole stay.', 'Cherry blossom late Mar–early Apr; Golden Week (late Apr–early May) is very busy.', 'Some common cold and allergy medicines are banned – check yours. Earthquake alerts worth turning on.', 'Priya and Hannah have been. Dan is planning a trip in April.', 'slip-on shoes for temples, a coin purse, a Type A adapter', 5, null),
  ('dest_vietnam', 'Vietnam', 'Vietnam', 'E-visa needed – apply online before you go. We’ll add a deadline to your calendar.', 'Lunar New Year (Tết) falls in Jan or Feb – lots closes for a few days.', 'See a travel clinic about recommended vaccines 6–8 weeks before you go.', 'Kofi is going in January. 31 Matche travellers are planning Vietnam this summer.', 'light rain jacket, mosquito repellent, quick-dry clothes', 0, null),
  ('dest_portugal', 'Portugal', 'Portugal', 'No visa needed for up to 90 days in the Schengen area. Check whether the new ETIAS travel authorisation applies to your dates.', 'Lisbon’s Santo António street festivals fill June; summer is peak season.', 'Low-risk destination. Strong sun from June to September.', 'Sophie is there right now and has been twice before.', 'grippy walking shoes for steep cobbles, a light layer for evenings', 0, null),
  ('dest_iceland', 'Iceland', 'Iceland', 'No visa needed for up to 90 days in the Schengen area. Check ETIAS for your dates.', 'Northern lights season roughly Sep–Mar; midnight sun in June.', 'Weather changes fast – check road and weather alerts daily if driving.', 'Ravi goes in February. It’s on 2 friends’ wishlists.', 'waterproof shell, thermal base layers, swimwear for hot pools', 0, null),
  ('dest_morocco', 'Morocco', 'Morocco', 'No visa needed for tourist stays up to 90 days.', 'Ramadan dates move each year – some cafés close during the day.', 'Stick to bottled or filtered water. Dress modestly away from tourist areas.', 'Tom is planning a trip and asking for tips.', 'light long sleeves, a scarf, a refillable filter bottle', 0, null),
  ('dest_peru', 'Peru', 'Peru', 'No visa needed for short tourist stays.', 'Inti Raymi in Cusco on 24 June. Rainy season in the Andes is roughly Dec–Mar.', 'Altitude sickness is common in Cusco – plan two slow days. Ask a clinic about the Amazon.', 'Rosa just got back and rated it 4.9.', 'warm layers for cold nights, sunscreen for altitude, broken-in boots', 0, null),
  ('dest_tasmania', 'Tasmania', 'Australia', 'Domestic trip – just bring photo ID.', 'Summer is best for walking; winter is cold but quiet.', 'Weather on mountain walks can turn quickly – register longer hikes.', 'Jordan did a similar route in September.', 'a proper rain jacket, warm layers even in summer', 0, null)
insert into public.destination_notes (id, destination_id, category, position, title, body) values
  ('dn_jp_sakura', 'dest_japan', 'events', 1, 'Cherry blossom season', 'overlaps your dates – expect busy parks and book Kyoto stays early.'),
  ('dn_jp_golden', 'dest_japan', 'events', 2, 'Golden Week', 'starts 29 Apr, after you leave – good timing, prices jump then.'),
  ('dn_jp_dance', 'dest_japan', 'events', 3, 'Spring dance performances', 'run in Kyoto’s geisha districts through April.'),
  ('dn_jp_meds', 'dest_japan', 'health', 1, 'Medication:', 'some common cold and allergy medicines are banned in Japan. Check yours before packing.'),
  ('dn_jp_vacc', 'dest_japan', 'health', 2, 'Vaccines:', 'make sure routine vaccines are current; ask a travel clinic about extras for rural stays.'),
  ('dn_jp_quake', 'dest_japan', 'health', 3, 'Earthquakes:', 'save your stays’ evacuation info and turn on emergency alerts.')
