insert into public.trip_reviews (trip_id, user_id, short_title, rating, journal_entry_count, highlight_quote, highlight_day, cover_tone, photo_tones) values
  ('trip_nz_south_2018', 'matthew', 'NZ South Island', 4.8, 19, 'Campervan heater died on night two. Wore every jumper I own and still rated the stars 10/10.', 3, '#2E4A45', array['#3D5A52', '#31455E', '#6E5432', '#2E4A45']::text[]),
  ('trip_vietnam_2019', 'matthew', 'Vietnam', 5, 41, 'Third bowl of cao lầu today. I may never leave Hoi An.', 11, '#6B4A2B', array['#6E5432', '#3D5A52', '#5A3A47', '#6B4A2B']::text[]),
  ('trip_bali_2022', 'matthew', 'Bali & Lombok', 4.5, 17, 'The ferry that broke down twice. Made four friends and learned a card game I still can’t explain.', 6, '#31455E', array['#31455E', '#2E4A45', '#6E5432', '#394B6A']::text[]),
  ('trip_singapore_2023', 'matthew', 'Singapore', 4.4, 8, 'Ate at five hawker stalls before noon. A personal best.', 1, '#5A3A47', array['#5A3A47', '#6B4A2B', '#394B6A', '#3D5A52']::text[]),
  ('trip_fiji_2023', 'matthew', 'Fiji', 4.7, 12, 'Snorkelled with a reef shark. Was calm about it for exactly zero seconds.', 4, '#394B6A', array['#394B6A', '#2E4A45', '#31455E', '#3D5A52']::text[]),
  ('trip_korea_2024', 'matthew', 'South Korea', 4.8, 23, 'Ordered entirely in Korean. Was understood. Was handed the wrong dish anyway. Delicious.', 2, '#3D5A52', array['#3D5A52', '#5A3A47', '#6B4A2B', '#394B6A']::text[]),
  ('trip_nz_north_2025', 'matthew', 'NZ North Island', 4.6, 14, 'Tongariro Crossing at 5am. Legs gone, soul restored.', 5, '#2E4A45', array['#2E4A45', '#6E5432', '#31455E', '#3D5A52']::text[]),
  ('trip_srilanka_2026', 'matthew', 'Sri Lanka', 4.9, 33, 'Up at 3:45 for the sunrise trek. Worth it the second the clouds broke.', 7, '#6E5432', array['#6E5432', '#3D5A52', '#5A3A47', '#2E4A45']::text[])
