insert into public.user_profiles (user_id, handle, hero_tone, about, style_tags, facts, ask_me_about, bucket_list, giving_back, notes_public, created_at) values
  ('matthew', 'matthewcheung', '#E0662F', 'Weekday spreadsheets, weekend train timetables. I plan trips around what I’m going to eat, then work backwards. Always up for a dawn hike if there’s a good breakfast at the bottom.', array['Food-led', 'Early riser', 'Trains over planes', 'Carry-on only']::text[], '[{"label":"Favourite spot","value":"Hoi An, Vietnam"},{"label":"Dream trip","value":"Patagonia on foot"},{"label":"Best meal abroad","value":"Street cao lầu"},{"label":"Languages","value":"English, some Korean"}]'::jsonb, array['Vietnam by train', 'NZ campervans', 'cheap eats in Seoul']::text[], array['Patagonia', 'Iceland in winter', 'Lisbon & Porto', 'Trans-Siberian rail', 'Oaxaca']::text[], '2 volunteering days logged: a beach clean-up in Bali and a turtle hatchery shift in Sri Lanka.', true, '2024-03-12T09:00:00Z')
