  ('note_linh', 'matthew', null, 'Linh', 'homestay host', 'LN', '#F6B08E', 'Hoi An, Vietnam', 'trip_vietnam_2019', 'Matthew ate more bánh mì than any guest we have had. Please come back and bring your appetite.', 'approved', true, '2019-09-20T08:00:00Z'),
  ('note_marta', 'matthew', null, 'Marta', 'fellow traveller', 'MV', '#C9B8E8', 'Gili Air ferry', 'trip_bali_2022', 'Best person to be stranded on a broken ferry with. Still owe you a game of cards.', 'approved', true, '2022-07-15T08:00:00Z'),
  ('note_ruwan', 'matthew', null, 'Ruwan', 'trek guide', 'RK', '#8FC7BF', 'Ella, Sri Lanka', 'trip_srilanka_2026', 'Never complained once about the 3:45am start. Strong legs, good jokes.', 'approved', true, '2026-02-16T08:00:00Z'),
  ('note_ben', 'matthew', null, 'Ben', 'hostel roommate', 'BH', '#E9D79A', 'Queenstown, NZ', 'trip_nz_south_2018', 'Snores like a campervan heater. Otherwise great.', 'approved', false, '2018-02-11T08:00:00Z'),
